<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> read_csv_labels</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">fname</span><span style="color:#ABB2BF;">):</span></span>
